$toString = function($value) use ($params, &$toString) {
    switch (gettype($value)) {
        case 'boolean': return \OpenDxp::getContainer()->get('translator')->trans($data ? 'yes' : 'no', [], 'admin');
        case 'NULL'   : return null;
        case 'object' :
        case 'array'  :
            if(isset($value['value'], $value['unit'])) {
                return implode(' ', $value);
            }

            if(isset($value['key'])) {
                return $value['key'];
            }

            $expressions = [];
            foreach ($value as $key => $item) {
                $serialized = $toString($item);
                if($serialized) {
                    $expressions[] = (!is_numeric($key) ? $key.': ' : '').$serialized;
                }
            }
            return implode(', ', $expressions);
    default: return (string)$value;
  }
};

$data = [];
$data['name'] = $toString($params['rawItemData']['name']['value']);
$data['TechnicalData'] = $toString($params['rawItemData']['TechnicalData']['value']);

$data = array_filter($data);

return implode("\n", array_map(
    function ($value, $field) { return $field.': '.$value; },
    $data,
    array_keys($data)
));

